package com.localbiz.model;
import java.time.LocalDate;
public class MarketingCampaign { private int campaignId,businessId; private String campaignName,description,status; private LocalDate startDate,endDate; public int getCampaignId(){return campaignId;} public void setCampaignId(int v){campaignId=v;} public int getBusinessId(){return businessId;} public void setBusinessId(int v){businessId=v;} public String getCampaignName(){return campaignName;} public void setCampaignName(String v){campaignName=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} }
